    # checkpoint tensor, so drop tensors of layers beyond num_hidden_layers
    # before the loop. Full-model runs (NUM_LAYERS unset) skip this edit.
    if [ -n "${NUM_LAYERS}" ]; then python3 - <<'PY'
    p="/usr/local/lib/python3.12/dist-packages/vllm/models/deepseek_v32/nvidia/model.py"
    s=open(p).read()
    anchor="        loaded_params: set[str] = set()\n"
    ins=anchor+("        _nl = self.config.num_hidden_layers\n"
        "        weights = ((n, w) for n, w in weights if not ((m := __import__('re').match(r'^(model\\.)?layers\\.(\\d+)\\.', n)) and int(m.group(2)) >= _nl))\n")
    assert s.count(anchor)==1, s.count(anchor)
    s=s.replace(anchor,ins)
    open(p,"w").write(s); print("patched loader for truncated layers")
    PY
    fi
    CANON=${CANONICAL_LAYOUT:-true}
    KV_TRANSFER_CONFIG='{"kv_connector":"OffloadingConnector","kv_role":"kv_both",
      "kv_load_failure_policy":"fail",
      "kv_connector_extra_config":{
        "spec_name":"TieringOffloadingSpec",
        "cpu_bytes_to_use":'"${KV_OFFLOAD_CPU_BYTES:-8589934592}"',
        "eviction_policy":"lru",
        "offload_prompt_only":false,
        "canonical_layout":'"$CANON"',
        "secondary_tiers":[{"type":"p2p","host":"'"${POD_IP}"'","port":7777},
          {"type":"fs","root_dir":"/mnt/shared/xtp-kv","n_read_threads":8,"n_write_threads":8}]}}'
    exec vllm serve zai-org/GLM-5.2-FP8 \
      --port 8000 \
      --trust-remote-code \
      --hf-overrides '{"num_hidden_layers": '"${NUM_LAYERS:-4}"', "num_nextn_predict_layers": 0}' \
      --load-format runai_streamer \
      --kv-cache-dtype fp8 \
      --tensor-parallel-size ${TP_SIZE:-1} \
      --gpu-memory-utilization ${GPU_MEM_UTIL:-0.85} \
      --max-model-len ${MAX_MODEL_LEN:-32768} \
      --max-num-batched-tokens 8192 \
      --block-size 64 \
      --disable-access-log-for-endpoints=/health,/metrics \
      --kv_transfer_config "$KV_TRANSFER_CONFIG" ${EXTRA_ARGS}
